/**
 * PRECISION PACK — fixtures-real generator.
 *
 * Reads the 10 vendored contract fixtures (src/lib/contract/__tests__/
 * fixtures/) and writes src/lib/contract/__tests__/fixtures-real/ — the SAME
 * games and file shape, but with every reachable position's gameEval entry
 * regenerated by REAL Stockfish over UCI (depth 16, MultiPV 3 — the serving
 * client's analysis settings). The v2 FP measurement
 * (contract_fidelity_eval.ts --fp-measure --fixtures-real) runs against
 * these so arming decisions rest on engine-true contracts: the v1
 * hand-authored evals put fabricated cp figures and 2-4-ply invented lines
 * in the license pools, contaminating the TF/FP adjudication.
 *
 * Faithfulness rules:
 *  - Eval convention mirrors src/lib/engine/helpers/parseResults.ts exactly:
 *    lines sorted by the side-to-move comparator FIRST, then cp/mate negated
 *    to White-perspective when Black is to move (including its `cp ? -cp :
 *    cp` zero-preserving quirk).
 *  - Per-position line COUNT mirrors the original fixture (1 line on quiet
 *    plies, 3 on the mistake plies) so contract shape/selection pressure
 *    stays comparable; PVs are capped at 4 plies like the originals so the
 *    referee license pools stay the same size class.
 *  - Structural sentinels are preserved VERBATIM: a position whose original
 *    entry has no usable line (empty lines / depth 0 / empty pv — fixture
 *    03's timeout sentinel) keeps its original entry, as does every position
 *    past an unreplayable SAN (fixture 04's "Qxz9" truncation) — those
 *    positions don't exist on any board, and the sentinels ARE the fixture.
 *  - Terminal positions (mate/stalemate on the board) get the uciEngine.ts
 *    terminal shape: single line, empty pv, depth 0, mate ±1 / cp 0.
 *  - Original fixtures + CI-1 snapshots are NOT touched.
 *
 * Usage (needs a `stockfish` binary on PATH — `brew install stockfish`):
 *   npx tsx scripts/eval/generate_fixture_evals.ts [--only 07] [--depth 16]
 */
import { spawn } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";
import { Chess } from "chess.js";

const REPO_ROOT = process.cwd();
const SRC_DIR = path.join(REPO_ROOT, "src/lib/contract/__tests__/fixtures");
const OUT_DIR = path.join(REPO_ROOT, "src/lib/contract/__tests__/fixtures-real");

const DEPTH = (() => {
  const i = process.argv.indexOf("--depth");
  return i >= 0 ? Number.parseInt(process.argv[i + 1] ?? "16", 10) : 16;
})();
const ONLY = (() => {
  const i = process.argv.indexOf("--only");
  return i >= 0 ? process.argv[i + 1] ?? null : null;
})();
const MULTIPV = 3;
const PV_CAP = 4; // originals carry 2-4-ply lines; keep license pools the same size class

interface FixtureLine {
  pv: string[];
  cp?: number;
  mate?: number;
  depth: number;
  multiPv: number;
}
interface FixturePosition {
  lines: FixtureLine[];
  bestMove?: string;
  [k: string]: unknown;
}
interface FixtureFile {
  moveHistory: string[];
  gameEval: { positions: FixturePosition[]; [k: string]: unknown };
  [k: string]: unknown;
}

// ── UCI driver ──────────────────────────────────────────────────────────────
class Engine {
  private stdin: NodeJS.WritableStream;
  private buffer = "";
  private waiters: Array<{ match: (line: string) => boolean; resolve: (lines: string[]) => void; lines: string[] }> = [];

  constructor(bin: string) {
    const proc = spawn(bin, [], { stdio: ["pipe", "pipe", "inherit"] });
    if (!proc.stdin || !proc.stdout) throw new Error("stockfish: no stdio pipes");
    this.stdin = proc.stdin;
    proc.stdout.setEncoding("utf8");
    proc.stdout.on("data", (chunk: string) => {
      this.buffer += chunk;
      let nl: number;
      while ((nl = this.buffer.indexOf("\n")) >= 0) {
        const line = this.buffer.slice(0, nl).trim();
        this.buffer = this.buffer.slice(nl + 1);
        if (!line) continue;
        const w = this.waiters[0];
        if (w) {
          w.lines.push(line);
          if (w.match(line)) {
            this.waiters.shift();
            w.resolve(w.lines);
          }
        }
      }
    });
  }

  send(cmd: string): void {
    this.stdin.write(cmd + "\n");
  }

  /** Send `cmd` and collect stdout lines until one matches `until`. */
  ask(cmd: string, until: (line: string) => boolean): Promise<string[]> {
    return new Promise((resolve) => {
      this.waiters.push({ match: until, resolve, lines: [] });
      this.send(cmd);
    });
  }

  quit(): void {
    this.send("quit");
    this.stdin.end();
  }
}

function getProp(line: string, prop: string): string | undefined {
  const parts = line.split(" ");
  const i = parts.indexOf(prop);
  return i >= 0 && i + 1 < parts.length ? parts[i + 1] : undefined;
}

/** Same comparator as parseResults.ts sortLines (side-to-move perspective). */
function sortLines(a: FixtureLine, b: FixtureLine): number {
  if (a.mate !== undefined && b.mate !== undefined) {
    const aDelivers = a.mate > 0;
    const bDelivers = b.mate > 0;
    if (aDelivers !== bDelivers) return aDelivers ? -1 : 1;
    return a.mate - b.mate;
  }
  if (a.mate !== undefined) return -a.mate;
  if (b.mate !== undefined) return b.mate;
  return (b.cp ?? 0) - (a.cp ?? 0);
}

/** Analyze one FEN: depth-16 multipv-3, White-perspective, PV capped. */
async function analyze(engine: Engine, fen: string, lineCount: number): Promise<FixturePosition> {
  const board = new Chess(fen);
  if (board.isGameOver()) {
    // uciEngine.ts terminal shape.
    if (board.isCheckmate()) {
      const mated = board.turn(); // side to move is the checkmated side
      return { lines: [{ pv: [], depth: 0, multiPv: 1, mate: mated === "w" ? -1 : 1 }], bestMove: undefined };
    }
    return { lines: [{ pv: [], depth: 0, multiPv: 1, cp: 0 }], bestMove: undefined };
  }

  const out = await engine.ask(`position fen ${fen}\ngo depth ${DEPTH}`, (l) => l.startsWith("bestmove"));
  const best: Record<string, FixtureLine> = {};
  let bestMove: string | undefined;
  for (const line of out) {
    if (line.startsWith("bestmove")) {
      const bm = getProp(line, "bestmove");
      bestMove = bm && bm !== "(none)" ? bm : undefined;
    }
    if (!line.startsWith("info") || !line.includes(" pv ")) continue;
    const multiPv = getProp(line, "multipv");
    const depth = getProp(line, "depth");
    if (!multiPv || !depth) continue;
    if (best[multiPv] && Number.parseInt(depth, 10) < best[multiPv].depth) continue;
    const cp = getProp(line, "cp");
    const mate = getProp(line, "mate");
    const pvIdx = line.split(" ").indexOf("pv");
    const pv = line.split(" ").slice(pvIdx + 1, pvIdx + 1 + PV_CAP);
    best[multiPv] = {
      pv,
      cp: cp !== undefined ? Number.parseInt(cp, 10) : undefined,
      mate: mate !== undefined ? Number.parseInt(mate, 10) : undefined,
      depth: Number.parseInt(depth, 10),
      multiPv: Number.parseInt(multiPv, 10),
    };
  }

  // Side-to-move sort first, THEN White-perspective normalization — exactly
  // parseResults.ts (including its zero-preserving negation quirk).
  let lines = Object.values(best).sort(sortLines).slice(0, lineCount);
  const whiteToPlay = fen.split(" ")[1] === "w";
  if (!whiteToPlay) {
    lines = lines.map((l) => ({ ...l, cp: l.cp ? -l.cp : l.cp, mate: l.mate ? -l.mate : l.mate }));
  }
  // Drop undefined cp/mate keys so the JSON matches the originals' shape.
  const clean = lines.map((l) => {
    const o: FixtureLine = { pv: l.pv, depth: l.depth, multiPv: l.multiPv };
    if (l.cp !== undefined) o.cp = l.cp;
    if (l.mate !== undefined) o.mate = l.mate;
    return o;
  });
  return { lines: clean, ...(bestMove ? { bestMove } : {}) };
}

/** A position entry with no usable line — fixture 03's timeout sentinel. */
function isSentinel(p: FixturePosition): boolean {
  return p.lines.length === 0 || p.lines.every((l) => l.depth === 0 || l.pv.length === 0);
}

async function main(): Promise<void> {
  const engine = new Engine(process.env.STOCKFISH_BIN ?? "stockfish");
  await engine.ask("uci", (l) => l === "uciok");
  engine.send(`setoption name MultiPV value ${MULTIPV}`);
  engine.send("setoption name Threads value 1"); // determinism over speed
  await engine.ask("isready", (l) => l === "readyok");

  fs.mkdirSync(OUT_DIR, { recursive: true });
  const names = fs
    .readdirSync(SRC_DIR)
    .filter((f) => f.endsWith(".json"))
    .filter((f) => (ONLY ? f.includes(ONLY) : true))
    .sort();

  for (const name of names) {
    const t0 = Date.now();
    const fixture = JSON.parse(fs.readFileSync(path.join(SRC_DIR, name), "utf8")) as FixtureFile;
    const { moveHistory, gameEval } = fixture;

    // Replay to collect reachable FENs; stop at the first unreplayable SAN
    // (fixture 04) — positions past it are preserved verbatim.
    const board = new Chess();
    const fens: Array<string | null> = [board.fen()];
    let truncated = false;
    for (const san of moveHistory) {
      if (!truncated) {
        try {
          board.move(san);
          fens.push(board.fen());
          continue;
        } catch {
          truncated = true;
        }
      }
      fens.push(null);
    }

    const positions: FixturePosition[] = [];
    let regenerated = 0;
    let preserved = 0;
    for (let i = 0; i < gameEval.positions.length; i++) {
      const original = gameEval.positions[i];
      const fen = fens[i] ?? null;
      if (fen === null || isSentinel(original)) {
        positions.push(original); // unreachable or sentinel — the fixture IS this
        preserved++;
        continue;
      }
      positions.push(await analyze(engine, fen, Math.max(1, Math.min(MULTIPV, original.lines.length))));
      regenerated++;
    }

    const out: FixtureFile = { ...fixture, gameEval: { ...gameEval, positions } };
    fs.writeFileSync(path.join(OUT_DIR, name), JSON.stringify(out, null, 2) + "\n");
    console.log(
      `${name}: ${regenerated} regenerated, ${preserved} preserved verbatim [${Date.now() - t0}ms]`,
    );
  }

  engine.quit();
  console.log(`\nwritten to ${OUT_DIR} (depth ${DEPTH}, multipv ${MULTIPV}, pv cap ${PV_CAP})`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
